// Drizzle schema (ADR-004). Tables as TS code; migrations are generated from
// this file with `npm run db:generate` and are forward-only.
import { sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  boolean,
  check,
  date,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// IDs are UUID v7 generated by the application (ADR-004) — no DB default.
const id = () => uuid("id").primaryKey();

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

export const users = pgTable("users", {
  id: id(),
  email: text("email").notNull().unique(), // stored lowercased
  passwordHash: text("password_hash").notNull(),
  emailVerifiedAt: timestamp("email_verified_at", { withTimezone: true }),
  ...timestamps,
});

export const roles = pgTable(
  "roles",
  {
    id: id(),
    key: text("key").notNull().unique(),
    name: text("name").notNull(),
    isDefault: boolean("is_default").notNull().default(false),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("roles_single_default")
      .on(t.isDefault)
      .where(sql`${t.isDefault}`),
  ],
);

export const permissions = pgTable("permissions", {
  id: id(),
  key: text("key").notNull().unique(),
  description: text("description").notNull(),
  ...timestamps,
});

export const rolePermissions = pgTable(
  "role_permissions",
  {
    roleId: uuid("role_id")
      .notNull()
      .references(() => roles.id, { onDelete: "cascade" }),
    permissionId: uuid("permission_id")
      .notNull()
      .references(() => permissions.id, { onDelete: "cascade" }),
    ...timestamps,
  },
  (t) => [primaryKey({ columns: [t.roleId, t.permissionId] })],
);

export const userRoles = pgTable(
  "user_roles",
  {
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    roleId: uuid("role_id")
      .notNull()
      .references(() => roles.id, { onDelete: "restrict" }),
    ...timestamps,
  },
  (t) => [primaryKey({ columns: [t.userId, t.roleId] })],
);

export const refreshTokens = pgTable(
  "refresh_tokens",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    familyId: uuid("family_id").notNull(),
    tokenHash: text("token_hash").notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    replacedBy: uuid("replaced_by").references(
      (): AnyPgColumn => refreshTokens.id,
    ),
    ...timestamps,
  },
  (t) => [index("refresh_tokens_user_id_idx").on(t.userId)],
);

export const emailVerificationTokens = pgTable("email_verification_tokens", {
  id: id(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  tokenHash: text("token_hash").notNull().unique(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  usedAt: timestamp("used_at", { withTimezone: true }),
  ...timestamps,
});

export const rateLimits = pgTable("rate_limits", {
  key: text("key").primaryKey(),
  windowStart: timestamp("window_start", { withTimezone: true }).notNull(),
  count: integer("count").notNull(),
  ...timestamps,
});

// --- Locations (Standorte) -------------------------------------------------
// Opening hours are times of day in local time Europe/Berlin, "HH:MM"
// (ADR-004 amendment). Stored as one jsonb value so version check and audit
// entry stay a single statement (ADR-015). Validated by Zod before writing.
export type StoredTimeRange = { weekday: string; start: string; end: string };

export const locations = pgTable(
  "locations",
  {
    id: id(),
    name: text("name").notNull(),
    kind: text("kind").notNull(),
    openingHours: jsonb("opening_hours")
      .$type<StoredTimeRange[]>()
      .notNull()
      .default([]),
    active: boolean("active").notNull().default(true),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("locations_name_lower_idx").on(sql`lower(${t.name})`),
    check(
      "locations_kind_check",
      sql`${t.kind} in ('customer_area', 'reception', 'training_center', 'other')`,
    ),
  ],
);

// --- Central audit log (ADR-015) — append-only -----------------------------
export const auditEvents = pgTable(
  "audit_events",
  {
    id: id(),
    entityType: text("entity_type").notNull(),
    entityId: uuid("entity_id").notNull(),
    action: text("action").notNull(),
    actorUserId: uuid("actor_user_id").references(() => users.id, {
      onDelete: "set null",
    }),
    occurredAt: timestamp("occurred_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    changes: jsonb("changes")
      .$type<Record<string, { from: unknown; to: unknown }>>()
      .notNull()
      .default({}),
    ...timestamps,
  },
  (t) => [
    index("audit_events_entity_idx").on(
      t.entityType,
      t.entityId,
      t.occurredAt.desc(),
    ),
  ],
);

// --- Staffing demand per location (Besetzungsbedarf) -----------------------
// Own row and own version, so opening hours and demand can be edited
// independently (ADR-015). Windows are local times (ADR-004), validated by Zod.
export type StoredStaffingWindow = {
  weekday: string;
  start: string;
  end: string;
  people: number;
};

export const locationStaffing = pgTable("location_staffing", {
  locationId: uuid("location_id")
    .primaryKey()
    .references(() => locations.id, { onDelete: "cascade" }),
  windows: jsonb("windows")
    .$type<StoredStaffingWindow[]>()
    .notNull()
    .default([]),
  version: integer("version").notNull().default(1),
  ...timestamps,
});

// --- Auswahllisten for employee profiles ------------------------------------
// Entries are never deleted, only deactivated; names unique per list
// (case-insensitive). Durations in minutes.
export const contractTypes = pgTable(
  "contract_types",
  {
    id: id(),
    name: text("name").notNull(),
    weeklyMinutes: integer("weekly_minutes").notNull(),
    typicalShiftMinutes: integer("typical_shift_minutes"),
    allowedShiftMinutes: integer("allowed_shift_minutes")
      .array()
      .notNull()
      .default(sql`'{}'::integer[]`),
    maxDailyMinutes: integer("max_daily_minutes"),
    active: boolean("active").notNull().default(true),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("contract_types_name_lower_idx").on(sql`lower(${t.name})`),
  ],
);

export const qualifications = pgTable(
  "qualifications",
  {
    id: id(),
    name: text("name").notNull(),
    active: boolean("active").notNull().default(true),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("qualifications_name_lower_idx").on(sql`lower(${t.name})`),
  ],
);

export const systemAccesses = pgTable(
  "system_accesses",
  {
    id: id(),
    name: text("name").notNull(),
    active: boolean("active").notNull().default(true),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("system_accesses_name_lower_idx").on(sql`lower(${t.name})`),
  ],
);

// --- Employees (Mitarbeiterprofile) — no login, maintained by the planner ----
// mobile is E.164; phone/e-mail are PII and never logged (ADR-013).
export const employees = pgTable(
  "employees",
  {
    id: id(),
    firstName: text("first_name").notNull(),
    lastName: text("last_name").notNull(),
    personnelNo: text("personnel_no"),
    mobile: text("mobile").notNull(),
    email: text("email"),
    contractTypeId: uuid("contract_type_id")
      .notNull()
      .references(() => contractTypes.id),
    weeklyMinutesOverride: integer("weekly_minutes_override"),
    isFloater: boolean("is_floater").notNull().default(false),
    note: text("note"),
    active: boolean("active").notNull().default(true),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    index("employees_name_idx").on(t.lastName, t.firstName),
    index("employees_contract_type_idx").on(t.contractTypeId),
  ],
);

export const employeeQualifications = pgTable(
  "employee_qualifications",
  {
    employeeId: uuid("employee_id")
      .notNull()
      .references(() => employees.id, { onDelete: "cascade" }),
    qualificationId: uuid("qualification_id")
      .notNull()
      .references(() => qualifications.id),
  },
  (t) => [primaryKey({ columns: [t.employeeId, t.qualificationId] })],
);

export const employeeSystemAccesses = pgTable(
  "employee_system_accesses",
  {
    employeeId: uuid("employee_id")
      .notNull()
      .references(() => employees.id, { onDelete: "cascade" }),
    systemAccessId: uuid("system_access_id")
      .notNull()
      .references(() => systemAccesses.id),
  },
  (t) => [primaryKey({ columns: [t.employeeId, t.systemAccessId] })],
);

export const employeeLocations = pgTable(
  "employee_locations",
  {
    employeeId: uuid("employee_id")
      .notNull()
      .references(() => employees.id, { onDelete: "cascade" }),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    trained: boolean("trained").notNull(),
    preference: text("preference").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.employeeId, t.locationId] }),
    check(
      "employee_locations_preference_check",
      sql`${t.preference} in ('preferred', 'neutral', 'blocked')`,
    ),
  ],
);

// --- Availability (Abwesenheiten + recurring rules) -------------------------
// Calendar dates + local "HH:MM" (ADR-004 exception "Planungsdaten mit
// Kalendertag"). Audit entries are written on the employee (ADR-015).
export const absences = pgTable(
  "absences",
  {
    id: id(),
    employeeId: uuid("employee_id")
      .notNull()
      .references(() => employees.id, { onDelete: "cascade" }),
    kind: text("kind").notNull(),
    startDate: date("start_date", { mode: "string" }).notNull(),
    endDate: date("end_date", { mode: "string" }).notNull(),
    startTime: text("start_time"),
    endTime: text("end_time"),
    note: text("note"),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    index("absences_employee_idx").on(t.employeeId, t.startDate),
    index("absences_range_idx").on(t.startDate, t.endDate),
    check(
      "absences_kind_check",
      sql`${t.kind} in ('vacation', 'absent', 'appointment', 'wish_off')`,
    ),
    check("absences_range_check", sql`${t.endDate} >= ${t.startDate}`),
    check(
      "absences_time_check",
      sql`(${t.startTime} is null and ${t.endTime} is null) or (${t.startTime} is not null and ${t.endTime} is not null and ${t.startDate} = ${t.endDate} and ${t.startTime} < ${t.endTime})`,
    ),
  ],
);

export const availabilityRules = pgTable(
  "availability_rules",
  {
    id: id(),
    employeeId: uuid("employee_id")
      .notNull()
      .references(() => employees.id, { onDelete: "cascade" }),
    weekdays: text("weekdays").array().notNull(),
    startTime: text("start_time"),
    endTime: text("end_time"),
    version: integer("version").notNull().default(1),
    ...timestamps,
  },
  (t) => [
    index("availability_rules_employee_idx").on(t.employeeId),
    check(
      "availability_rules_weekdays_check",
      sql`cardinality(${t.weekdays}) between 1 and 7 and ${t.weekdays} <@ array['mon','tue','wed','thu','fri','sat','sun']::text[]`,
    ),
    check(
      "availability_rules_time_check",
      sql`${t.startTime} is null or ${t.endTime} is null or ${t.startTime} < ${t.endTime}`,
    ),
  ],
);
